3	import java.security.Principal;
4	import java.time.Duration;
5	import java.time.Instant;
6	import java.util.UUID;
7	import lombok.AllArgsConstructor;
8	import lombok.extern.slf4j.Slf4j;
9	import org.apache.commons.lang3.StringUtils;
10	import org.jspecify.annotations.Nullable;
11	import org.springframework.dao.OptimisticLockingFailureException;
12	import org.springframework.data.domain.Sort;
13	import org.springframework.security.core.context.ReactiveSecurityContextHolder;
14	import org.springframework.security.core.context.SecurityContext;
15	import org.springframework.util.Assert;
16	import reactor.core.publisher.Flux;
17	import reactor.core.publisher.Mono;
18	import reactor.util.retry.Retry;
19	import run.halo.app.core.extension.content.Snapshot;
20	import run.halo.app.extension.ListOptions;
21	import run.halo.app.extension.MetadataUtil;
22	import run.halo.app.extension.ReactiveExtensionClient;
23	import run.halo.app.extension.Ref;
24	import run.halo.app.extension.index.query.Queries;
25	import run.halo.app.extension.router.selector.FieldSelector;
26	
27	/**
28	 * Abstract Service for {@link Snapshot}.
29	 *
30	 * @author guqing
31	 * @since 2.0.0
32	 */
33	@Slf4j
34	@AllArgsConstructor
35	public abstract class AbstractContentService {
36	
37	    private final ReactiveExtensionClient client;
38	
39	    public Mono<ContentWrapper> getContent(String snapshotName, String baseSnapshotName) {
40	        if (StringUtils.isBlank(snapshotName) || StringUtils.isBlank(baseSnapshotName)) {
41	            return Mono.empty();
42	        }
43	        // TODO: refactor this method to use client.get instead of fetch but please be careful
44	        return client.fetch(Snapshot.class, baseSnapshotName)
45	                .doOnNext(this::checkBaseSnapshot)
46	                .flatMap(baseSnapshot -> {
47	                    if (StringUtils.equals(snapshotName, baseSnapshotName)) {
48	                        var contentWrapper = ContentWrapper.patchSnapshot(baseSnapshot, baseSnapshot);
49	                        return Mono.just(contentWrapper);
50	                    }
51	                    return client.fetch(Snapshot.class, snapshotName)
52	                            .map(snapshot -> ContentWrapper.patchSnapshot(snapshot, baseSnapshot));
53	                })
54	                .switchIfEmpty(Mono.defer(() -> {
55	                    log.error(
56	                            "The content snapshot [{}] or base snapshot [{}] not found.",
57	                            snapshotName,
58	                            baseSnapshotName);
59	                    return Mono.empty();
60	                }));
61	    }
62	
63	    protected void checkBaseSnapshot(Snapshot snapshot) {
64	        Assert.notNull(snapshot, "The snapshot must not be null.");
65	        if (!Snapshot.isBaseSnapshot(snapshot)) {
66	            throw new IllegalArgumentException(String.format(
67	                    "The snapshot [%s] is not a base snapshot.",
68	                    snapshot.getMetadata().getName()));
69	        }
70	    }
71	
72	    protected Mono<ContentWrapper> draftContent(
73	            @Nullable String baseSnapshotName, ContentRequest contentRequest, @Nullable String parentSnapshotName) {
74	        return create(baseSnapshotName, contentRequest, parentSnapshotName).flatMap(head -> {
75	            String baseSnapshotNameToUse = StringUtils.defaultIfBlank(
76	                    baseSnapshotName, head.getMetadata().getName());
77	            return restoredContent(baseSnapshotNameToUse, head);
78	        });
79	    }
80	
81	    protected Mono<ContentWrapper> draftContent(String baseSnapshotName, ContentRequest content) {
82	        return this.draftContent(baseSnapshotName, content, content.headSnapshotName());
83	    }
84	
85	    private Mono<Snapshot> create(
86	            @Nullable String baseSnapshotName, ContentRequest contentRequest, @Nullable String parentSnapshotName) {
87	        Snapshot snapshot = contentRequest.toSnapshot();
88	        snapshot.getMetadata().setName(UUID.randomUUID().toString());
89	        snapshot.getSpec().setParentSnapshotName(parentSnapshotName);
90	
91	        return client.fetch(Snapshot.class, baseSnapshotName)
92	                .doOnNext(this::checkBaseSnapshot)
93	                .defaultIfEmpty(snapshot)
94	                .map(baseSnapshot -> determineRawAndContentPatch(snapshot, baseSnapshot, contentRequest))
95	                .flatMap(source -> getContextUsername()
96	                        .doOnNext(username -> {
97	                            Snapshot.addContributor(source, username);
98	                            source.getSpec().setOwner(username);
99	                        })
100	                        .thenReturn(source))
101	                .flatMap(client::create);
102	    }
103	
104	    protected Mono<ContentWrapper> updateContent(String baseSnapshotName, ContentRequest contentRequest) {
105	        Assert.notNull(contentRequest, "The contentRequest must not be null");
106	        Assert.notNull(baseSnapshotName, "The baseSnapshotName must not be null");
107	        Assert.notNull(contentRequest.headSnapshotName(), "The headSnapshotName must not be null");
108	        return Mono.defer(() -> client.fetch(Snapshot.class, contentRequest.headSnapshotName())
109	                        .flatMap(headSnapshot -> {
110	                            var oldVersion = contentRequest.version();
111	                            var version = headSnapshot.getMetadata().getVersion();
112	                            if (hasConflict(oldVersion, version)) {
113	                                // draft a new snapshot as the head snapshot
114	                                return create(baseSnapshotName, contentRequest, contentRequest.headSnapshotName());
115	                            }
116	                            return Mono.just(headSnapshot);
117	                        })
118	                        .flatMap(headSnapshot -> client.fetch(Snapshot.class, baseSnapshotName)
119	                                .map(baseSnapshot ->
120	                                        determineRawAndContentPatch(headSnapshot, baseSnapshot, contentRequest)))
121	                        .flatMap(headSnapshot -> getContextUsername()
122	                                .doOnNext(username -> Snapshot.addContributor(headSnapshot, username))
123	                                .thenReturn(headSnapshot))
124	                        .flatMap(client::update))
125	                .retryWhen(Retry.backoff(5, Duration.ofMillis(100))
126	                        .filter(throwable -> throwable instanceof OptimisticLockingFailureException))
127	                .flatMap(head -> restoredContent(baseSnapshotName, head));
128	    }
129	
130	    protected Flux<Snapshot> listSnapshotsBy(Ref ref) {
131	        var snapshotListOptions = new ListOptions();
132	        var query = Queries.isNull("metadata.deletionTimestamp")
133	                .and(Queries.equal("spec.subjectRef", Snapshot.toSubjectRefKey(ref)));
134	        snapshotListOptions.setFieldSelector(FieldSelector.of(query));
135	        var sort = Sort.by("metadata.creationTimestamp", "metadata.name").descending();
136	        return client.listAll(Snapshot.class, snapshotListOptions, sort);
137	    }
138	
139	    boolean hasConflict(Long oldVersion, Long newVersion) {
140	        return oldVersion != null && !newVersion.equals(oldVersion);
141	    }
142	
143	    protected Mono<ContentWrapper> restoredContent(String baseSnapshotName, Snapshot headSnapshot) {
144	        return client.fetch(Snapshot.class, baseSnapshotName)
145	                .doOnNext(this::checkBaseSnapshot)
146	                .map(baseSnapshot -> ContentWrapper.patchSnapshot(headSnapshot, baseSnapshot));
147	    }
148	
149	    protected Snapshot determineRawAndContentPatch(
150	            Snapshot snapshotToUse, Snapshot baseSnapshot, ContentRequest contentRequest) {
151	        Assert.notNull(baseSnapshot, "The baseSnapshot must not be null.");
152	        Assert.notNull(contentRequest, "The contentRequest must not be null.");
153	        Assert.notNull(snapshotToUse, "The snapshotToUse not be null.");
154	        String originalRaw = baseSnapshot.getSpec().getRawPatch();
155	        String originalContent = baseSnapshot.getSpec().getContentPatch();
156	        String baseSnapshotName = baseSnapshot.getMetadata().getName();
157	
158	        snapshotToUse.getSpec().setLastModifyTime(Instant.now());
159	        // it is the v1 snapshot, set the content directly
160	        if (StringUtils.equals(baseSnapshotName, snapshotToUse.getMetadata().getName())) {
161	            snapshotToUse.getSpec().setRawPatch(contentRequest.raw());
162	            snapshotToUse.getSpec().setContentPatch(contentRequest.content());
163	            MetadataUtil.nullSafeAnnotations(snapshotToUse).put(Snapshot.KEEP_RAW_ANNO, Boolean.TRUE.toString());
164	        } else {
165	            // otherwise diff a patch based on the v1 snapshot
166	            String revisedRaw = contentRequest.rawPatchFrom(originalRaw);
167	            String revisedContent = contentRequest.contentPatchFrom(originalContent);
168	            snapshotToUse.getSpec().setRawPatch(revisedRaw);
169	            snapshotToUse.getSpec().setContentPatch(revisedContent);
170	        }
171	        return snapshotToUse;
172	    }
173	
174	    protected Mono<String> getContextUsername() {
175	        return ReactiveSecurityContextHolder.getContext()
176	                .map(SecurityContext::getAuthentication)
177	                .map(Principal::getName);
178	    }
179	}
